class ASMV1HttpClient(HttpClient):
    """ This class provides a client for the ASM V1 API. """

    def __init__(self, base_url, connection_alias):
        super(ASMV1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/asm/v1"

    def get_vnfcs_states(self, timeout=30):
        endpoint = '/vnfcs'
