    def change_local_account_state(self, account_type, enable, timeout=30):
        account_type = account_type.replace("Bts", "BTS")

        endpoint = '/account/users/system'

        user_role = {
            "BTSSecurity": "secUserAccessMode",
            "BTSApplication": "appUserAccessMode",
            "BTSRead": "readOnlyUserAccessMode"
        }

        headers = {
            "Content-Type": "application/json",
            "X-Nokia-Username": "Nemuadmin",
            "X-Nokia-Accessmode": "rw",
            "X-Nokia-Userrole": user_role[account_type]
        }

        payload = {
            "username": b64encode(account_type.encode('utf-8')).decode('ascii'),
            "activeStatus": "active" if enable else "deactive",
        }
        return self._send_patch_request(endpoint=endpoint, payload=payload, timeout=timeout, headers=headers)

    def add_netconf_accounts(self, accounts_info, authentication_method="deactivation_at_first_connection", timeout=30):
        endpoint = '/account/ssd/oru'
        authentication_methods = {
            "deactivation_at_first_connection": "DeactivationOfSSHPublicKeyValidationAtFirstConnection",
            "public_key_based": "PublicKeyBased"
        }

        headers = {
            "Content-Type": "application/json",
        }

        payload = {
            "authenticationMethodSshServer": authentication_methods[authentication_method],
            "sensitiveParams": accounts_info
        }

        response = self._send_post_request(endpoint=endpoint, json=payload, timeout=timeout, headers=headers)

        if response["status"] == "failure":
            raise RuntimeError(f"Failed to add netconf accounts, reason: {response['indicationResult']} "
                               f"{response['oruAccountResults'][0]['feedback']}")

        return response

