    def get_tree_of_current_plan(self, timeout=30):
        return self._send_get_request(endpoint='/current-plan/plan-tree-diff', timeout=timeout)

    def get_rnic_info_from_plan(self, timeout=30):
        current_plan_tree = self.get_tree_of_current_plan()["created"]
        rnicmod_runtime_distnames = [mo["distName"] for mo in current_plan_tree if "RNICMOD_R" in mo["name"]]

        rnicmod_info = {}
        for rnicmod in rnicmod_runtime_distnames:
            rnicmod_info[rnicmod] = self._send_get_request(endpoint="/current-plan/managed-object-parameters",
                                                           payload = {"distName": rnicmod},
                                                           timeout=timeout)

        return self._process_rnic_info(rnicmod_info=rnicmod_info)

    def perform_commissioning(self, scf_file, timeout=30):
        plan_name = path.splitext(path.split(scf_file)[1])[0]
        self.add_plan_to_staging(scf_file=scf_file, plan_name=plan_name, timeout=timeout)
        staged_plans = self._send_get_request(endpoint="/staged-plans", timeout=timeout)

        return self.activate_staged_plan(plan_name=plan_name, staged_plans=staged_plans, timeout=timeout)

    def get_status_of_perform_commissioning(self, plan_id, operation_id, timeout=30):
        return self._send_get_request(endpoint=f"/staged-plans/{plan_id}/operations/activations/{operation_id}",
                                      timeout=timeout)

    def add_plan_to_staging(self, scf_file, plan_name, timeout, **additional_param):
        with open(scf_file, "rb") as file:
            multipart_data = MultipartEncoder(
                fields={"planFile": (plan_name, file, "text/xml"),
                        "planName": plan_name,
                        **additional_param})

            result = self._send_post_request(endpoint="/staged-plans/actions/downloads", data=str(multipart_data),
                                             timeout=timeout, headers={"Content-Type": multipart_data.content_type},
                                             log_payload=False)

        time.sleep(5)  # Wait for the plan to be staged
        return result

    def activate_staged_plan(self, staged_plans, plan_name, timeout):
        for plan in staged_plans:
            if plan["planName"] == plan_name:
                plan_id = plan["planId"]
                response = self._send_post_request(endpoint=f"/staged-plans/{plan_id}/operations/activations",
                                                   timeout=timeout,
                                                   headers={"Content-Type": "application/json"})
                response["planId"] = plan_id

                return response

    def _process_rnic_info(self, rnicmod_info):
        desired_parameters = {
            'activeSwVersion': 'active_sw_version',
            'hwVersion': 'hw_version',
            'nokiaPN': 'nokia_pn',
            'operationalState': 'operational_state',
            'proceduralStatus': 'procedural_status',
            'productCode': 'product_code',
            'productName': 'product_name',
            'serialNumber': 'serial_number',
            'usageState': 'usage_state',
            'availabilityStatus': 'availability_status'
        }
        processed_info = []
        for runtime_distname, parameters in rnicmod_info.items():
            info = self._extract_parameters(runtime_distname, parameters, desired_parameters)
            if 'availability_status' not in info.keys():
                info['availability_status'] = 'on line'

            processed_info.append(info)

        return processed_info

    @staticmethod
    def _extract_parameters(runtime_distname, parameters, desired_parameters):
        info = {'r_nic_mod_dist_name': runtime_distname}
        for parameter in parameters["parameters"]:
            parameter_name = parameter["simpleParameter"]["name"]
            if parameter_name in desired_parameters:
                info[desired_parameters[parameter_name]] = parameter["simpleParameter"]["value"]

        return info

